package grammars_test

// Code generated by gen_go_tests.py from the corpus tests that the extended
// tree-sitter-haskell grammar adds to test/corpus/*.txt; DO NOT EDIT.

import (
	"testing"
	"time"

	gotreesitter "github.com/odvcencio/gotreesitter"
	"github.com/odvcencio/gotreesitter/grammars"
)

// TestHaskellGrammarExtensionsMatchC pins the trees of the constructs that the
// extended grammar adds. Each want is the tree that `tree-sitter test` accepts
// for the C parser generated from the same grammar.
func TestHaskellGrammarExtensionsMatchC(t *testing.T) {
	entry := grammars.DetectLanguageByName("haskell")
	if entry == nil {
		t.Fatal("haskell grammar is not registered")
	}
	lang := entry.Language()
	for _, tc := range haskellGrammarExtensionCases {
		t.Run(tc.name, func(t *testing.T) {
			// The corpus source, and the same source with a final newline.
			for _, src := range []string{tc.source, tc.source + "\n"} {
				done := make(chan struct{})
				var tree *gotreesitter.Tree
				var err error
				go func() {
					defer close(done)
					tree, err = gotreesitter.NewParser(lang).Parse([]byte(src))
				}()
				select {
				case <-done:
				case <-time.After(30 * time.Second):
					t.Fatal("parse did not finish within 30s")
				}
				if err != nil {
					t.Fatal(err)
				}
				root := tree.RootNode()
				if got := root.SExpr(lang); got != tc.want {
					t.Errorf("SExpr = %s\nwant    %s", got, tc.want)
				}
				if root.HasError() {
					t.Errorf("unexpected parse error")
				}
				tree.Release()
			}
		})
	}
}

